mapper.select:
SELECT pg.id, pg.user_id AS userId, u.nickname AS userNickname, pg.keyword, pg.style, pg.elements, pg.color_theme AS colorTheme, pg.usage_scene AS usageScene, pg.description, pg.reference_image_url AS referenceImageUrl, pg.prompt_text AS promptText, pg.generate_count AS generateCount, pg.status, pg.error_message AS errorMessage, pg.created_at AS createdAt FROM pattern_generation pg LEFT JOIN user u ON pg.user_id = u.id WHERE pg.deleted = 0
AND pg.user_id = #{userId}
AND (pg.keyword LIKE CONCAT('%', #{keyword}, '%') OR pg.description LIKE CONCAT('%', #{keyword}, '%'))
AND pg.style = #{style}
AND pg.status = #{status}
AND pg.created_at >= #{startTime}
AND pg.created_at <= #{endTime}
ORDER BY pg.created_at DESC
